#include <stdio.h>

void twice(int *p) { *p *= 2; }

int main(void) {
    int n = 21;
    twice(&n);
    printf("%d\n", n); /* 42 */
    return 0;
}

#include <stdio.h>
#include <string.h>

int main(void) {
    char s[10] = "TCS";
    printf("%zu %zu\n", sizeof s, strlen(s)); /* 10 3 */
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int *a = calloc(5, sizeof *a);
    if (a == NULL) return 1;
    a[2] = 7;
    printf("%d %d\n", a[0], a[2]); /* 0 7 */
    free(a);
    a = NULL;
    return 0;
}

#include <stdio.h>

int next_id(void) {
    static int id = 100;
    return ++id;
}

int main(void) {
    next_id();
    printf("%d\n", next_id()); /* 102 */
    return 0;
}

